// A captured form layout, and its structure as Frappe's form drew it (Phase II, owner 21-11-2026).
//
// The layouts are the old site's own form definitions (layouts/*.json, generated by
// scripts/analysis/extract_layouts.py from the live capture of 21-11-2026). Frappe laid a form out
// from its flat field list: a Tab Break starts a tab (the fields before the first one are the first
// tab, "Details"), a Section Break a section, a Column Break a column. Pure.

export interface LayoutField {
  fieldname: string;
  label?: string;
  fieldtype: string;
  options?: string;
  hidden?: boolean;
  reqd?: boolean;
  readOnly?: boolean;
  dependsOn?: string;
  mandatoryDependsOn?: string;
  readOnlyDependsOn?: string;
  collapsible?: boolean;
  collapsibleDependsOn?: string;
  bold?: boolean;
  inListView?: boolean;
  inStandardFilter?: boolean;
  columns?: number;
  precision?: string;
  description?: string;
  allowOnSubmit?: boolean;
  default?: string;
  fetchFrom?: string;
  printHide?: boolean;
  nonNegative?: boolean;
  /** Left out of a copy (Duplicate, Amend: Frappe copy_doc). */
  noCopy?: boolean;
  /** Permission level (0 when absent): only level-0 fields were named in the old timeline. */
  permlevel?: number;
}

export interface DoctypeLayout {
  doctype: string;
  module?: string | null;
  istable: boolean;
  issingle: boolean;
  isSubmittable: boolean;
  /** ERPNext's naming rule ("naming_series:", "field:item_code", "hash", a pattern…). */
  autoname?: string | null;
  /** A link to this DocType shows its title, not its name. */
  showTitleFieldInLink?: boolean;
  titleField: string | null;
  sortField: string;
  sortOrder: string;
  searchFields: string | null;
  defaultPrintFormat: string | null;
  fields: LayoutField[];
}

export interface FormSection {
  label: string | null;
  collapsible: boolean;
  collapsibleDependsOn: string | null;
  dependsOn: string | null;
  columns: LayoutField[][];
}

export interface FormTab {
  label: string;
  fieldname: string | null;
  dependsOn: string | null;
  sections: FormSection[];
}

/** Field types that hold no value (layout only). */
export const LAYOUT_TYPES = new Set(["Tab Break", "Section Break", "Column Break"]);

/** The form's tabs, sections and columns, in the old order. Hidden breaks still break (as in Frappe). */
export function structure(layout: DoctypeLayout): FormTab[] {
  const tabs: FormTab[] = [];
  let tab: FormTab = { label: "Details", fieldname: null, dependsOn: null, sections: [] };
  let section: FormSection | null = null;
  const newSection = (f?: LayoutField) => {
    section = {
      label: f?.label ?? null,
      collapsible: !!f?.collapsible,
      collapsibleDependsOn: f?.collapsibleDependsOn ?? null,
      dependsOn: f && !f.hidden ? f.dependsOn ?? null : null,
      columns: [[]],
    };
    if (f?.hidden) section.dependsOn = "eval:false";
    tab.sections.push(section);
    return section;
  };
  for (const f of layout.fields) {
    if (f.fieldtype === "Tab Break") {
      if (tab.sections.length || tabs.length === 0) tabs.push(tab);
      tab = { label: f.label ?? "", fieldname: f.fieldname, dependsOn: f.hidden ? "eval:false" : f.dependsOn ?? null, sections: [] };
      section = null;
      continue;
    }
    if (f.fieldtype === "Section Break") {
      newSection(f);
      continue;
    }
    const s: FormSection = section ?? newSection();
    if (f.fieldtype === "Column Break") {
      s.columns.push([]);
      continue;
    }
    s.columns[s.columns.length - 1].push(f);
  }
  tabs.push(tab);
  // The first tab exists even when the layout starts with a Tab Break; drop it only if empty.
  return tabs.filter((t, i) => t.sections.length || i > 0);
}

/** The child-table field's layout name (its options), for Table fields. */
export const isTable = (f: LayoutField) => f.fieldtype === "Table" || f.fieldtype === "Table MultiSelect";
